#include <stdio.h>
#include <string.h>

struct Student {
    char name[32];
    int age;
};

int main() {
    struct Student s;
    strncpy(s.name, "Alexandria Smith", sizeof(s.name) - 1);
    s.name[sizeof(s.name) - 1] = '\0';
    s.age = 20;
    printf("%s is %d\n", s.name, s.age);
    return 0;
}
